"""Position sets: the committed golden set (generated by golden.py) and, optionally, the
positions of Stockfish's own 'bench' command, read at run time from the upstream source the
build checked out (never committed here)."""

import json
import re


def load_golden(path):
    out = []
    with open(path, "r", encoding="ascii") as f:
        for line in f:
            line = line.strip()
            if line:
                p = json.loads(line)
                p.setdefault("moves", [])
                p["stm"] = _stm(p["fen"], p["moves"])
                out.append(p)
    return out


def _stm(fen, moves):
    side = fen.split()[1]
    if len(moves) % 2 == 1:
        side = "b" if side == "w" else "w"
    return side


def load_sfbench(benchmark_cpp):
    """The standard-chess positions of src/benchmark.cpp's Defaults list (Chess960 entries and
    setoption lines skipped); 'fen moves a b' entries keep their moves."""
    with open(benchmark_cpp, "r", encoding="utf-8") as f:
        text = f.read()
    start = text.index("Defaults = {")
    end = text.index("};", start)
    out = []
    chess960 = False
    for line in text[start:end].splitlines():
        code = line.split("//")[0]
        for s in re.findall(r'"([^"]*)"', code):
            if s.startswith("setoption name UCI_Chess960 value"):
                chess960 = s.endswith("true")
                continue
            if chess960 or s.startswith("setoption"):
                continue
            fen, _, moves = s.partition(" moves ")
            mv = moves.split() if moves else []
            out.append({"id": "sfb-%02d" % (len(out) + 1), "fen": fen.strip(), "moves": mv,
                        "cat": "sfbench", "stm": _stm(fen, mv)})
    return out
